{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (principal is null || resource is null || request is null)
            return Deny("missing-context");

        var identityFailure = GetIdentityFailure(principal, resource);
        if (identityFailure is not null)
            return Deny(identityFailure);

        var requestFailure = GetRequestFailure(principal, resource, request);
        if (requestFailure is not null)
            return Deny(requestFailure);

        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        if (request.BreakGlass)
            return DecideBreakGlass(administrator, request.StrongAuthentication);

        return DecideStandardAccess(
            resource,
            request,
            administrator,
            operatorRole,
            auditor,
            owner,
            delegated);
    }

    private static string? GetIdentityFailure(Principal principal, Resource resource)
    {
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return "invalid-identity";
        if (principal.Suspended)
            return "principal-suspended";
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return "tenant-mismatch";

        return null;
    }

    private static string? GetRequestFailure(Principal principal, Resource resource, AccessRequest request)
    {
        if (resource.Locked && request.Action != "read")
            return "resource-locked";
        if (request.MinuteOfDay is < 0 or > 1439)
            return "invalid-time";
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return "challenge-required";

        return null;
    }

    private static AccessDecision DecideBreakGlass(bool administrator, bool strongAuthentication)
    {
        return administrator && strongAuthentication
            ? new AccessDecision(true, "break-glass", true)
            : Deny("invalid-break-glass");
    }

    private static AccessDecision DecideStandardAccess(
        Resource resource,
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        var restrictionFailure = GetRestrictionFailure(resource, request);
        if (restrictionFailure is not null)
            return Deny(restrictionFailure);

        return request.Action switch
        {
            "delete" => DecideDelete(resource, request, administrator, delegated),
            "write" => DecideWrite(resource, request, administrator, operatorRole, owner, delegated),
            "read" => DecideRead(resource, request, administrator, operatorRole, auditor, owner, delegated),
            _ => Deny("unknown-action")
        };
    }

    private static string? GetRestrictionFailure(Resource resource, AccessRequest request)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return "strong-authentication-required";
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return "trusted-network-required";

        return null;
    }

    private static AccessDecision DecideDelete(
        Resource resource,
        AccessRequest request,
        bool administrator,
        bool delegated)
    {
        return administrator
            ? Allow(resource, request, delegated)
            : Deny("administrator-required");
    }

    private static AccessDecision DecideWrite(
        Resource resource,
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool owner,
        bool delegated)
    {
        return administrator || operatorRole || owner || delegated
            ? Allow(resource, request, delegated)
            : Deny("write-not-authorised");
    }

    private static AccessDecision DecideRead(
        Resource resource,
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        return administrator || operatorRole || auditor || owner || delegated
            ? Allow(resource, request, delegated)
            : new AccessDecision(false, "read-not-authorised", false);
    }

    private static AccessDecision Allow(Resource resource, AccessRequest request, bool delegated)
    {
        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private static AccessDecision Deny(string reason)
    {
        return new AccessDecision(false, reason, true);
    }
}
